#include <Keypad.h>
#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

// --- Настройка клавиатуры 4x4 ---
const byte ROWS = 4; 
const byte COLS = 4; 

char keys[ROWS][COLS] = {
  {'1','2','3','A'},
  {'4','5','6','B'},
  {'7','8','9','C'},
  {'*','0','#','D'}
};
// Пины, к которым подключены строки и столбцы
byte rowPins[ROWS] = {4, 5, 6, 7};    // R1, R2, R3, R4
byte colPins[COLS] = {8, 9, 10, 11};  // C1, C2, C3, C4

Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

// Переменная для защиты от залипания (антидребезг)
unsigned long lastPressTime = 0;
const unsigned long debounceDelay = 1000; // 1 секунда между нажатиями

void setup() {
  USB.begin();
  Keyboard.begin();
  delay(1000); // Даем ПК время распознать плату
  Serial.begin(115200);
  Serial.println("Система готова. Нажмите 1 (Выкл) или 2 (Перезагрузка).");
}

void loop() {
  char key = keypad.getKey();

  if (key) {
    // Проверка на антидребезг
    if (millis() - lastPressTime > debounceDelay) {
      lastPressTime = millis();

      if (key == '1') {
        Serial.println("Нажата 1: Выключение ПК...");
        sendCommand("shutdown /s /t 0");
      } 
      else if (key == '2') {
        Serial.println("Нажата 2: Перезагрузка ПК...");
        sendCommand("shutdown /r /t 0");
      }
    }
  }
}

// Функция для отправки команды на ПК
void sendCommand(String cmd) {
  // 1. Переключение на английскую раскладку (Win + Space)
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press(' ');
  delay(50);
  Keyboard.releaseAll();
  delay(200);

  // 2. Открываем "Выполнить" (Win + R)
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(50);
  Keyboard.releaseAll();
  delay(300); 

  // 3. Вводим "cmd" и жмем Enter
  Keyboard.print("cmd");
  delay(50);
  Keyboard.write(KEY_RETURN);
  delay(400); 

  // 4. Вводим саму команду и жмем Enter
  Keyboard.print(cmd);
  delay(50);
  Keyboard.write(KEY_RETURN);

  // Небольшая пауза, чтобы команда успела выполниться
  delay(500); 
}
